{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Fluticasone, a lipophilic corticosteroid with multiple polar groups, has absolute oral bioavailability <1% via gastrointestinal absorption in humans, demonstrating that complex steroid-like molecules can have negligible oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sitostanol, a fused-ring plant stanol with a hydroxyl group, had absolute oral bioavailability of only 0.04% in healthy subjects after oral administration, directly supporting very low F for a structurally related lipophilic terpenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Mometasone, a corticosteroid with a similar fused-ring scaffold and polar substituents, is reported to have low oral bioavailability (<1%) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Rifaximin, a large polycyclic molecule with multiple polar groups, has confirmed minimal oral absorption in healthy volunteers with less than 0.4% orally bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Docetaxel has low absolute oral bioavailability in humans due to extensive hepatic and intestinal first-pass extraction, a relevant metabolic liability for the query's oxidizable terpenoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Andrographolide, a diterpenoid with hydroxyls and a lactone, showed poor oral bioavailability in human volunteers after tablet administration, supporting low F for the query's diterpenoid acid scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including direct absolute bioavailability measurements in humans, show very low oral bioavailability (<1% or lower) for complex terpenoid/steroid-like molecules sharing the query's fused-ring scaffold, polar groups, and metabolic liability. The query's carboxylic acid and acetyl/hydroxyl pattern further favor poor absorption and extensive first-pass metabolism, so F is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "The exact permeability and first-pass metabolism profile of the query's specific diterpenoid acid scaffold is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

